-- 1. Consulta sin índice: Escaneo secuencial lento
EXPLAIN ANALYZE
SELECT * FROM transacciones WHERE usuario_id = 952341;
-- Resultado: Seq Scan on transacciones (cost=0.00..184520.10 rows=4 width=128) (actual time=4250.12 ms)

-- 2. Creación del índice B-Tree para acelerar búsquedas por usuario
CREATE INDEX idx_transacciones_usuario_id ON transacciones (usuario_id);

-- 3. Misma consulta con índice: Búsqueda inmediata
EXPLAIN ANALYZE
SELECT * FROM transacciones WHERE usuario_id = 952341;
-- Resultado: Index Scan using idx_transacciones_usuario_id (cost=0.43..8.45 rows=4) (actual time=0.08 ms)
